import { SupportedLanguage } from "../i18n/languages";
import { ISRAEL_LOCATIONS } from "./israelLocations";
import { normalizeLocationText } from "./locationSearch";

// ---------------------------------------------------------------------------
// Shared REAL schools dataset — every entry here is a real, officially
// registered educational institution from Israel's Ministry of Education open
// data (data.gov.il): "מאפייני מוסדות חינוך בפיקוח משרד החינוך" (institution
// characteristics) joined with "קואורדינטות מוסדות החינוך" (institution
// coordinates) by institution code (סמל מוסד). 2015 is the latest year
// available in that government resource as of this writing — treat this the
// same way as israelLocations.ts's own curated snapshot: real, but not
// continuously live-synced. Never add a generated/templated name (e.g.
// "<City> School") here — extend from the same government source instead.
//
// Scoped to schools located in (or matched to the nearest of) one of the
// localities already in israelLocations.ts, via `areaLocationId` — this is
// what lets the school picker filter its suggestions to the trip's actual
// From/To area (see SchoolAutocomplete.tsx's `areaLocationId` prop).
//
// A handful of names (well under 1%) still carry a single leftover quote
// character from the government source's own CSV export — real Hebrew
// educational abbreviations (ת"ת, חט"ב, בי"ס, ...) legitimately use the
// same quote/geresh character internally, so those cannot be safely
// stripped by a blanket rule without risking corrupting a real name
// elsewhere. Left as-is rather than guessed at.
//
// Display localization (getLocalizedSchoolName/getLocalizedSchoolCity, near
// the bottom of this file): the government source only publishes Hebrew
// names, so there is no authoritative Arabic/English/Russian translation to
// pull from. Rather than leaving every non-Hebrew UI showing raw Hebrew
// text, this file applies a disclosed, best-effort localization: the city
// portion of a name is swapped for the SAME real, already-curated
// translation already used for that locality everywhere else in the app
// (israelLocations.ts), and common structural education terms ("יסודי" =
// Elementary, "מקיף" = Comprehensive, ...) are translated via a small fixed
// dictionary. Any remaining fragment (a unique proper name/person's name
// not covered by either) is left in Hebrew rather than guessed at — this is
// a display convenience, never a claim that the Ministry of Education
// publishes these translations.
// ---------------------------------------------------------------------------

export type SchoolLocation = {
  id: string;
  // Real official name as registered with the Ministry of Education —
  // Hebrew only, since that is the only name this government source
  // publishes. See getLocalizedSchoolName below for how this is shown in
  // other app languages.
  name: string;
  // Real city/town/village name (שם ישוב) as registered.
  city: string;
  // The israelLocations.ts locality id this school belongs to (matched by
  // city name, or by nearest real coordinates when the two datasets used
  // slightly different city-name spellings).
  areaLocationId: string;
  latitude: number;
  longitude: number;
};

