export const SCHOOLS: SchoolLocation[] = RAW_SCHOOLS.map(
  ([id, name, city, areaLocationId, latitude, longitude]) => ({
    id,
    name,
    city,
    areaLocationId,
    latitude,
    longitude,
  }),
);

export const findSchoolById = (id: string): SchoolLocation | null =>
  SCHOOLS.find((school) => school.id === id) || null;

// ---------------------------------------------------------------------------
// Search — school names are real and Hebrew-only (see SchoolLocation.name
// above), so matching always normalizes as Hebrew (diacritics stripped,
// final-letter forms normalized) regardless of the app's current UI
// language — there is no other-language name to switch to. Results are
// ALWAYS scoped to a specific area (areaLocationId, e.g. the trip's
// currently selected To/From locality) — never a nationwide free search —
// so the picker only ever suggests schools that actually make sense for the
// selected trip area. See SchoolAutocomplete.tsx's `areaLocationId` prop.
// ---------------------------------------------------------------------------

export const MAX_SCHOOL_RESULTS = 25;

// `language` determines which text a typed query is matched against — the
// real Hebrew name for Hebrew UIs, or the localized display name (see
// getLocalizedSchoolName below) for every other language, so a parent using
// the app in Arabic/English/Russian can actually type a term like "ابتدائية"
// / "Elementary" / "Начальная" and find matching schools, not just Hebrew.
export function searchSchools(
  query: string,
  areaLocationId: string | null,
  language: SupportedLanguage = "he",
): SchoolLocation[] {
  if (!areaLocationId) return [];

  const pool = SCHOOLS.filter(
    (school) => school.areaLocationId === areaLocationId,
  );

  const trimmed = String(query || "").trim();
  const matchLanguage = language === "he" ? "hebrew" : undefined;

  const displayText = (school: SchoolLocation) =>
    language === "he" ? school.name : getLocalizedSchoolName(school, language);

  // No text typed yet: show every school already known for this area (still
  // capped) so the picker feels populated the moment an area is chosen,
  // rather than requiring the parent/driver to already know a school's name.
  if (!trimmed) {
    return pool.slice(0, MAX_SCHOOL_RESULTS);
  }

  const needle = normalizeLocationText(trimmed, matchLanguage);
  if (!needle) return pool.slice(0, MAX_SCHOOL_RESULTS);

  const starts: SchoolLocation[] = [];
  const contains: SchoolLocation[] = [];

  for (const school of pool) {
    const haystack = normalizeLocationText(displayText(school), matchLanguage);
    if (!haystack) continue;

    if (haystack.startsWith(needle)) {
      starts.push(school);
    } else if (haystack.includes(needle)) {
      contains.push(school);
    }
  }

  const byName = (a: SchoolLocation, b: SchoolLocation) =>
    displayText(a).localeCompare(displayText(b), language === "he" ? "he" : language);

  return [...starts.sort(byName), ...contains.sort(byName)].slice(
    0,
    MAX_SCHOOL_RESULTS,
  );
}

// ---------------------------------------------------------------------------
// Display localization — see the file-header comment for what this is and
// is not (a disclosed best-effort display convenience, never an
// authoritative government translation).
// ---------------------------------------------------------------------------

const AREA_BY_ID = new Map(ISRAEL_LOCATIONS.map((loc) => [loc.id, loc]));

const LOCALIZED_NAME_FOR_LANGUAGE: Record<
  Exclude<SupportedLanguage, "he">,
  "arabic" | "english"
> = {
  ar: "arabic",
  en: "english",
  // israelLocations.ts has no Russian column yet — English is the closest
  // Latin-script fallback (see locationSearch.ts's APP_LANGUAGE_TO_INPUT_LANGUAGE).
  ru: "english",
};

// Common Hebrew educational-institution terms → {ar, en, ru}. Ordered
// longest-Hebrew-term-first so e.g. "על יסודי" (post-elementary) is replaced
// before the plain "יסודי" (elementary) it contains, and 'ת"ת'/'תלמוד תורה'
// (the same institution type, abbreviated vs. spelled out) both resolve to
// the same translation. Sourced from the terms that actually appear in the
// real dataset above — extend here (never invent a new city/school name) if
// a future data refresh introduces a term not yet covered.
const SCHOOL_TERM_DICTIONARY: [string, { ar: string; en: string; ru: string }][] = [
  ["תלמוד תורה", { ar: "تلمود توراة", en: "Talmud Torah", ru: "Талмуд-Тора" }],
  ["חטיבת ביניים", { ar: "متوسطة", en: "Middle School", ru: "Неполная средняя школа" }],
  ["על יסודי", { ar: "فوق ابتدائية", en: "Post-Elementary", ru: "Неполная средняя" }],
  ["בית ספר", { ar: "مدرسة", en: "School", ru: "Школа" }],
  ["אולפנה", { ar: "أولفانا", en: "Ulpana", ru: "Ульпана" }],
  ['חט"ב', { ar: "متوسطة", en: "Middle School", ru: "Неполная средняя школа" }],
  ['בי"ס', { ar: "مدرسة", en: "School", ru: "Школа" }],
  ['ת"ת', { ar: "تلمود توراة", en: "Talmud Torah", ru: "Талмуд-Тора" }],
  ['ע"ש', { ar: "باسم", en: "Named After", ru: "Имени" }],
  ["תיכון", { ar: "ثانوية", en: "High School", ru: "Средняя школа" }],
  ["מקיף", { ar: "الشامل", en: "Comprehensive", ru: "Общеобразовательная" }],
  ["יסודי", { ar: "ابتدائية", en: "Elementary", ru: "Начальная" }],
  ["ממלכתי", { ar: "حكومية", en: "State", ru: "Государственная" }],
  ["אולפן", { ar: "أولبان", en: "Ulpan", ru: "Ульпан" }],
  ["סמינר", { ar: "معهد ديني", en: "Seminary", ru: "Семинария" }],
  ["ישיבה", { ar: "يشيفا", en: "Yeshiva", ru: "Йешива" }],
  ["מיוחד", { ar: "تربية خاصة", en: "Special Education", ru: "Специальное образование" }],
  ["דמוקרטי", { ar: "ديمقراطية", en: "Democratic", ru: "Демократическая" }],
  ["ניסויי", { ar: "تجريبية", en: "Experimental", ru: "Экспериментальная" }],
  ["פנימיה", { ar: "داخلية", en: "Boarding School", ru: "Интернат" }],
  ["דתי", { ar: "دينية", en: "Religious", ru: "Религиозная" }],
  ["ערבי", { ar: "عربية", en: "Arab", ru: "Арабская" }],
  ["אורט", { ar: "أورط", en: "ORT", ru: "ОРТ" }],
];

// Splits on every occurrence of `needle` and rejoins with `replacement` —
// same semantics as String.replaceAll without requiring the ES2021 target.
const replaceAllOccurrences = (text: string, needle: string, replacement: string) =>
  needle ? text.split(needle).join(replacement) : text;

// Real, human-readable name for `school` in `language`. Returns the
// authoritative Hebrew name unchanged for "he" (and as the fallback for any
// fragment this function can't translate) — see the file-header comment for
// what "localized" means here.
export function getLocalizedSchoolName(
  school: SchoolLocation,
  language: SupportedLanguage,
): string {
  if (language === "he") return school.name;

  const nameField = LOCALIZED_NAME_FOR_LANGUAGE[language];
  let text = school.name;

  const area = AREA_BY_ID.get(school.areaLocationId);
  if (area) {
    const localizedArea = area[nameField] || area.english;
    if (localizedArea) {
      text = replaceAllOccurrences(text, area.hebrew, localizedArea);
    }
  }

  for (const [hebrewTerm, translations] of SCHOOL_TERM_DICTIONARY) {
    text = replaceAllOccurrences(text, hebrewTerm, translations[language]);
  }

  return text.trim();
}

// The school's city/area name in `language` — reuses the SAME real,
// already-curated locality translation as every From/To field in the app
// (israelLocations.ts), never a separate guess.
export function getLocalizedSchoolCity(
  school: SchoolLocation,
  language: SupportedLanguage,
): string {
  if (language === "he") return school.city;

  const area = AREA_BY_ID.get(school.areaLocationId);
  if (!area) return school.city;

  const nameField = LOCALIZED_NAME_FOR_LANGUAGE[language];
  return area[nameField] || area.english;
}
